cd /app && python3 - <<'PY'
p='parsing/html/reader.go'
s=open(p).read()
old='''		content := string(data[i+1 : tagEnd])
		selfClosing := false
		trimmed := strings.TrimSpace(content)
		if strings.HasSuffix(trimmed, "/") {
			selfClosing = true
			trimmed = strings.TrimSpace(strings.TrimSuffix(trimmed, "/"))
		}
		tag, attrs := parseTagAndAttrs(trimmed)'''
new='''		content := string(data[i+1 : tagEnd])
		trimmed, selfClosing := stripSelfClosing(content)
		tag, attrs := parseTagAndAttrs(trimmed)'''
assert old in s
s=s.replace(old,new)
# add stripSelfClosing function before parseTagAndAttrs
anchor='''func parseTagAndAttrs(s string) (string, []htmlAttr) {'''
helper='''func stripSelfClosing(s string) (string, bool) {
	s = strings.TrimSpace(s)
	if !strings.HasSuffix(s, "/") {
		return s, false
	}
	i := len(s) - 2
	for i >= 0 && isSpaceByte(s[i]) {
		i--
	}
	if i < 0 {
		return strings.TrimSpace(strings.TrimSuffix(s, "/")), true
	}
	j := i
	for j >= 0 && !isSpaceByte(s[j]) && s[j] != '=' {
		j--
	}
	lastToken := s[j+1 : i+1]
	hasEquals := strings.Contains(lastToken, "=")
	if hasEquals {
		// The slash is part of an unquoted attribute value.
		return s, false
	}
	return strings.TrimSpace(strings.TrimSuffix(s, "/")), true
}

'''
assert anchor in s
s=s.replace(anchor, helper+anchor)
open(p,'w').write(s)
